package progress

import (
	"net/http"
	"strconv"
	"time"

	"github.com/gin-gonic/gin"
	"gorm.io/gorm"

	"streak/internal/db"
	"streak/internal/httpapi"
	"streak/internal/period"
)

// Register adds a habit's progress and history.
func Register(r httpapi.Routes) {
	h := handler{d: r.Deps}
	r.Member.GET("/habits/:id/progress", httpapi.Handle(h.progress))
	r.Member.GET("/habits/:id/history", httpapi.Handle(h.history))
}

type handler struct{ d httpapi.Deps }

// liveDates are the dates of the habit's non-deleted check-ins from from to to.
func liveDates(q *gorm.DB, habitID string, from, to time.Time) ([]time.Time, error) {
	var dates []time.Time
	err := q.Model(&db.Completion{}).
		Where("habit_id = ? AND deleted_at IS NULL AND date BETWEEN ? AND ?", habitID, from, to).
		Pluck("date", &dates).Error
	return dates, err
}

// Of is the progress of a loaded habit at the user's today (for progress, home, nudges).
func Of(q *gorm.DB, h db.Habit, today time.Time) (Result, error) {
	w := WindowFor(h.Period, h.StartDate, h.EndDate, today)
	dates, err := liveDates(q, h.ID, w.AS, w.AE)
	if err != nil {
		return Result{}, err
	}
	return Compute(h.ID, w, h.TargetCount, dates), nil
}

// progress is GET /v1/habits/{id}/progress (R95-R108).
func (h handler) progress(c *gin.Context) error {
	who := httpapi.CallerOf(c)
	id, err := httpapi.PathUUID(c, "id")
	if err != nil {
		return err
	}
	_, today, err := h.d.Today(c, who.Timezone)
	if err != nil {
		return err
	}
	habit, err := db.OwnedHabit(h.d.Q(c), who.UserID, id)
	if err != nil {
		return err
	}
	res, err := Of(h.d.Q(c), habit, today)
	if err != nil {
		return err
	}
	c.JSON(http.StatusOK, res)
	return nil
}

// history is GET /v1/habits/{id}/history (R143-R147).
func (h handler) history(c *gin.Context) error {
	who := httpapi.CallerOf(c)
	id, err := httpapi.PathUUID(c, "id")
	if err != nil {
		return err
	}
	limit := 12
	if s, ok := c.GetQuery("limit"); ok {
		n, err := strconv.Atoi(s)
		if err != nil || n < 1 || n > 100 {
			return httpapi.Invalid("limit", "limit must be an integer from 1 to 100")
		}
		limit = n
	}
	_, today, err := h.d.Today(c, who.Timezone)
	if err != nil {
		return err
	}
	q := h.d.Q(c)
	habit, err := db.OwnedHabit(q, who.UserID, id)
	if err != nil {
		return err
	}
	if today.Before(habit.StartDate) {
		return httpapi.Conflict("habit_not_started", "the habit has not started yet")
	}
	var rows []db.HabitTarget
	if err := q.Where("habit_id = ?", id).Find(&rows).Error; err != nil {
		return err
	}
	targets := make([]Target, 0, len(rows))
	for _, r := range rows {
		targets = append(targets, Target{From: r.EffectiveFrom, Count: r.TargetCount})
	}
	end := period.AddDays(period.Start(today, habit.Period), -1)
	if habit.EndDate != nil {
		end = period.Min(end, *habit.EndDate)
	}
	dates, err := liveDates(q, id, habit.StartDate, end)
	if err != nil {
		return err
	}
	c.JSON(http.StatusOK, gin.H{"items": History(habit.Period, habit.StartDate, habit.EndDate,
		today, targets, habit.TargetCount, dates, limit)})
	return nil
}
